import React from "react";
import {observer} from 'mobx-react';
import {observable} from 'mobx';

import {Dates} from "utils/Utils";
import APageListReadWrite from "views/APageListReadWrite";
import NavItem from 'components/navs/NavItem';
import ConfirmDialog from 'components/dialogs/ConfirmDialog';
import {ActionsButton, ClearableInput} from 'components/inputs';
import {THead, TRow} from 'components/tables';

import NewKPIDialog from './dialogs/NewKPIDialog';
import ProfileKPIDialog from './dialogs/ProfileKPIDialog';

import style from "./KPITab.lazy.css";

@observer
class KPITab extends React.Component {
    path;
    pageKey = "KPITab";
    
    @observable state = {
        lists: {
            target_groups: [
                {text: 'Employee', value: 'Employee', checked: false}, 
                {text: 'Department', value: 'Department', checked: false}, 
                {text: 'Company', value: 'Company', checked: false}
            ]
        }
    };

    constructor(props) {
        super(props);

        this.path = props.path + 'kpi/';
        
        this.renderItem = this.renderItem.bind(this);
        this.renderPopoverOptions = this.renderPopoverOptions.bind(this);
        this.renderFilterNode = this.renderFilterNode.bind(this);
    }

    componentWillMount() {
        style.use();
    }

    componentWillUnmount() {
        style.unuse();
    }

    renderPopoverOptions(idx, {onView, onEdit, onRemove, Options}) {
        return <Options idx={idx} permissionModKey={this.props.permissionKey}>
            <NavItem action="view" onClick={onView} faIconLeft="eye" title="View"/>
            {/*<NavItem action="edit" onClick={onEdit} faIconLeft="edit" title="Edit"/>*/}
            <NavItem action="remove" onClick={onRemove} faIconLeft="ban" title="Remove"/>
        </Options>;
    }

    renderFilterNode(onChange) {
        const {isEmployee} = storage.is;
        return <div className="col-lg-12 controls flex">
            <ClearableInput name="created_at" type="date" placeholder="Date Created..." className="fixed-flex min-w-220 form-control" onChange={onChange}/>
            {!isEmployee && <ClearableInput name="target_group" type="radio" placeholder="Target" className="fixed-flex min-w-485 form-control" onChange={onChange} values={this.state.lists.target_groups}/>}
            {!isEmployee && <ClearableInput name="name" type="text" placeholder="Department/Employee Name" className="form-control" onChange={onChange}/>}
        </div>;
    }

    renderTHead() {
        return <THead>
            <div className="td fixed-flex min-w-120">Date Created</div>
            <div className="td">Target</div>
            <div className="td">Department/Employee Name</div>
            <div className="td fixed-flex padding-l-0 padding-r-0 min-w-60"></div>
        </THead>;
    }

    renderItem(n, onClick) {
        const item = this.refs.root.list[n];
        const {id, data: {created_at, target_group, name}} = item;
        return <TRow key={"item-" + n}>
            <div className="td fixed-flex min-w-120">{Dates.formatDate(created_at)}</div>
            <div className="td">{target_group}</div>
            <div className="td">{name}</div>
            <div className="td fixed-flex padding-l-10 padding-r-0 min-w-50">
            	<ActionsButton idx={n} className="btn btn-primary pull-right min-w-40" onClick={onClick}/>
            </div>
        </TRow>;
    }

    render() {
        return <APageListReadWrite 
            hasBackBtn={false}
            ref="root"
            page={this}
            createBtnTitle="Create"
            pageId={this.pageKey + "-tab"}
            pageTitle="Key Perfomance Indicator"
            pageTitleSingular="key perfomance indicator"
            path={this.path}
            noAnimation={true}
            renderPopoverOptions={this.renderPopoverOptions}
            renderFilterNode={this.renderFilterNode}
            renderTHead={this.renderTHead}
            renderItem={this.renderItem}>
            <ConfirmDialog ref="removeDialog"/>
            
            <NewKPIDialog ref="newDialog"/>
            <ProfileKPIDialog ref="profileDialog"/>
        </APageListReadWrite>;
    }
}

export default KPITab;
